INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_GOE_AGARES_GOET','ENT_GOE_AGARES','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Agares','The Second Spirit is a Duke called Agreas, or Agares. He is under the Power of the East, and cometh up in the form of an old fair Man, riding upon a Crocodile, carrying a Goshawk upon his fist, and yet mild in appearance. He maketh them to run that stand still, and bringeth back runaways. He teaches all Languages or Tongues presently.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_AIM_GOET','ENT_GOE_AIM','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Aim (Aym / Haborym)','The Twenty-third Spirit is Aim. He is a Great Strong Duke. He appeareth in the form of a very handsome Man in body, but with three Heads; the first, like a Serpent, the second like a Man having two Stars on his Forehead, the third like a Calf. He rideth on a Viper, carrying a Firebrand in his Hand, wherewith he setteth cities, castles, and great Places, on fire.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_ALLOCES_GOET','ENT_GOE_ALLOCES','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Alloces','The Fifty-second Spirit is Alloces, or Alocas. He is a Duke, Great, Mighty, and Strong, appearing in the Form of a Soldier riding upon a Great Horse. His Face is like that of a Lion, very Red, and having Flaming Eyes. His Speech is hoarse and very big. His Office is to teach the Art of Astronomy, and all the Liberal Sciences. He bringeth unto thee Good Familiars; also he ruleth over 36 Legions of Spirits.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_AMDUSIAS_GOET','ENT_GOE_AMDUSIAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Amdusias','The Sixty-seventh Spirit is Amdusias, or Amdukias. He is a Duke Great and Strong, appearing at first like a Unicorn, but at the request of the Exorcist he standeth before him in Human Shape, causing Trumpets, and all manner of Musical Instruments to be heard, but not soon or immediately. Also he can cause Trees to bend and incline according to the Exorcist''s Will. He giveth Excellent Familiars.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_AMON_GOET','ENT_GOE_AMON','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Amon','The Seventh Spirit is Amon. He is a Marquis great in power, and most stern. He appeareth like a Wolf with a Serpent''s tail, vomiting out of his mouth flames of fire; but at the command of the Magician he putteth on the shape of a Man with Dog''s teeth beset in a head like a Raven; or else like a Man with a Raven''s head (simply). He telleth all things Past and to Come.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_AMY_GOET','ENT_GOE_AMY','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Amy','The Fifty-eighth Spirit is Amy, or Avnas. He is a Great President, and appeareth at first in the Form of a Flaming Fire; but after a while he putteth on the Shape of a Man. His office is to make one Wonderful Knowing in Astrology and all the Liberal Sciences. He giveth Good Familiars, and can bewray Treasure that is kept by Spirits. He governeth 36 Legions of Spirits, and his Seal is this, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_ANDRAS_GOET','ENT_GOE_ANDRAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Andras','The Sixty-third Spirit is Andras. He is a Great Marquis, appearing in the Form of an Angel with a Head like a Black Night Raven, riding upon a strong Black Wolf, and having a Sharp and Bright Sword flourished aloft in his hand. His Office is to sow Discords. If the Exorcist have not a care, he will slay both him and his fellows. He governeth 30 Legions of Spirits, and this is his Seal, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_ANDREALPHUS_GOET','ENT_GOE_ANDREALPHUS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Andrealphus','The Sixty-fifth Spirit is Andrealphus. He is a Mighty Marquis, appearing at first in the form of a Peacock, with great Noises. But after a time he putteth on Human shape. He can teach Geometry perfectly. He maketh Men very subtle therein; and in all Things pertaining unto Mensuration or Astronomy. He can transform a Man into the Likeness of a Bird. He governeth 30 Legions of Infernal Spirits, and his Seal is this, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_ANDROMALIUS_GOET','ENT_GOE_ANDROMALIUS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Andromalius','The Seventy-second Spirit in Order is named Andromalius. He is an Earl, Great and Mighty, appearing in the Form of a Man holding a Great Serpent in his Hand. His Office is to bring back both a Thief, and the Goods which be stolen; and to discover all Wickedness, and Underhand Dealing; and to punish all Thieves and other Wicked People and also to discover Treasures that be Hid. He ruleth over 36 Legions of Spirits.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_ASMODAY_GOET','ENT_GOE_ASMODAY','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Asmoday','The Thirty-second Spirit is Asmoday, or Asmodai. He is a Great King, Strong, and Powerful. He appeareth with Three Heads, whereof the first is like a Bull, the second like a Man, and the third like a Ram; he hath also the tail of a Serpent, and from his mouth issue Flames of Fire. His Feet are webbed like those of a Goose. He sitteth upon an Infernal Dragon, and beareth in his hand a Lance with a Banner.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_ASTAROTH_GOET','ENT_GOE_ASTAROTH','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Astaroth','The Twenty-ninth Spirit is Astaroth. He is a Mighty, Strong Duke, and appeareth in the Form of an hurtful Angel riding on an Infernal Beast like a Dragon, and carrying in his right hand a Viper. Thou must in no wise let him approach too near unto thee, lest he do thee damage by his Noisome Breath. Wherefore the Magician must hold the Magical Ring near his face, and that will defend him.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_BAEL_GOET','ENT_GOE_BAEL','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Bael','The First Principal Spirit is a King ruling in the East, called Bael. He maketh thee to go Invisible. He ruleth over 66 Legions of Infernal Spirits. He appeareth in divers shapes, sometimes like a Cat, sometimes like a Toad, and sometimes like a Man, and sometimes all these forms at once. He speaketh hoarsely.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_BALAM_GOET','ENT_GOE_BALAM','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Balam','The Fifty-first Spirit is Balam or Balaam. He is a Terrible, Great, and Powerful King. He appeareth with three Heads: the first is like that of a Bull; the second is like that of a Man; the third is like that of a Ram. He hath the Tail of a Serpent, and Flaming Eyes. He rideth upon a furious Bear, and carrieth a Boshawk upon his Fist. He speaketh with a hoarse Voice, giving True Answers of Things Past, Present, and to Come.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_BARBATOS_GOET','ENT_GOE_BARBATOS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Barbatos','The Eighth Spirit is Barbatos. He is a Great Duke, and appeareth when the Sun is in Sagittary, with four noble Kings and their companies of great troops. He giveth understanding of the singing of Birds, and of the Voices of other creatures, such as the barking of Dogs. He breaketh the Hidden Treasures open that have been laid by the Enchantments of Magicians.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_BATHIN_GOET','ENT_GOE_BATHIN','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Bathin','The Eighteenth Spirit is Bathin. He is a Mighty and Strong Duke, and appeareth like a Strong Man with the tail of a Serpent, sitting upon a Pale-Coloured Horse. He knoweth the Virtues of Herbs and Precious Stones, and can transport men suddenly from one country to another. He ruleth over 30 Legions of Spirits. His Seal is this which is to be worn as aforesaid. (19.) SALLOS.—The Nineteenth Spirit is Sallos (or Saleos).','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_BELETH_GOET','ENT_GOE_BELETH','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Beleth','The Thirteenth Spirit is called Beleth (or Bileth, or Bilet). He is a mighty King and terrible. He rideth on a pale horse with trumpets and other kinds of musical instruments playing before him.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_BELIAL_GOET','ENT_GOE_BELIAL','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Belial (Goetia)','The Sixty-eighth Spirit is Belial. He is a Mighty and a Powerful King, and was created next after LUCIFER. He appeareth in the Form of Two Beautiful Angels sitting in a Chariot of Fire. He speaketh with a Comely Voice, and declareth that he fell first from among the worthier sort, that were before Michael, and other Heavenly Angels.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_BERITH_GOET','ENT_GOE_BERITH','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Berith','The Twenty-eighth Spirit in Order, as Solomon bound them, is named Berith. He is a Mighty, Great, and Terrible Duke. He hath two other Names given unto him by men of later times, viz.: BEALE, or BEAL, and BOFRY or BOLFRY. He appeareth in the Form of a Soldier with Red Clothing, riding upon a Red Horse, and having a Crown of Gold upon his head. He giveth true answers, Past, Present, and to Come.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_BIFRONS_GOET','ENT_GOE_BIFRONS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Bifrons','The Forty-sixth Spirit is called Bifrons, or Bifröus, or Bifrovs. He is an Earl, and appeareth in the Form of a Monster; but after a while, at the Command of the Exorcist, he putteth on the shape of a Man. His Office is to make one knowing in Astrology, Geometry, and other Arts and Sciences. He teacheth the Virtues of Precious Stones and Woods.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_BOTIS_GOET','ENT_GOE_BOTIS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Botis','The Seventeenth Spirit is Botis, a Great President, and an Earl. He appeareth at the first show in the form of an ugly Viper, then at the command of the Magician he putteth on a Human shape with Great Teeth, and two Horns, carrying a bright and sharp Sword in his hand. He telleth all things Past, and to Come, and reconcileth Friends and Foes. He ruleth over 60 Legions of Spirits, and this is his Seal, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_BUER_GOET','ENT_GOE_BUER','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Buer','The Tenth Spirit is Buer, a Great President. He appeareth in Sagittary, and that is his shape when the Sun is there. He teaches Philosophy, both Moral and Natural, and the Logic Art, and also the Virtues of all Herbs and Plants. He healeth all distempers in man, and giveth good Familiars.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_CAIM_GOET','ENT_GOE_CAIM','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Caim','The Fifty-third Spirit is Camio, or Caim. He is a Great President, and appeareth in the Form of the Bird called a Thrush at first, but afterwards he putteth on the Shape of a Man carrying in his Hand a Sharp Sword. He seemeth to answer in Burning Ashes, or in Coals of Fire. He is a Good Disputer.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_CIMEJES_GOET','ENT_GOE_CIMEJES','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Cimejes (Kimaris)','The Sixty-sixth Spirit is Cimejes, or Cimeies, or Kimaris. He is a Marquis, Mighty, Great, Strong and Powerful, appearing like a Valiant Warrior riding upon a goodly Black Horse. He ruleth over all Spirits in the parts of Africa. His Office is to teach perfectly Grammar, Logic, Rhetoric, and to discover things Lost or Hidden, and Treasures. He governeth 20 Legions of Infernals; and his Seal is this, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_CROCELL_GOET','ENT_GOE_CROCELL','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Crocell','The Forty-ninth Spirit is Crocell, or Crokel. He appeareth in the Form of an Angel. He is a Duke Great and Strong, speaking something Mystically of Hidden Things. He teacheth the Art of Geometry and the Liberal Sciences. He, at the Command of the Exorcist, will produce Great Noises like the Rushings of many Waters, although there be none. He warmeth Waters, and discovereth Baths.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_DANTALION_GOET','ENT_GOE_DANTALION','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Dantalion','The Seventy-first Spirit is Dantalion. He is a Duke Great and Mighty, appearing in the Form of a Man with many Countenances, all Men''s and Women''s Faces; and he hath a Book in his right hand. His Office is to teach all Arts and Sciences unto any; and to declare the Secret Counsel of any one; for he knoweth the Thoughts of all Men and Women, and can change them at his Will.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_DECARABIA_GOET','ENT_GOE_DECARABIA','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Decarabia','The Sixty-ninth Spirit is Decarabia. He appeareth in the Form of a Star in a Pentacle, at first; but after, at the command of the Exorcist, he putteth on the image of a Man. His Office is to discover the Virtues of Birds and Precious Stones, and to make the Similitude of all kinds of Birds to fly before the Exorcist, singing and drinking as natural Birds do. He governeth 30 Legions of Spirits, being himself a Great Marquis.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_ELIGOS_GOET','ENT_GOE_ELIGOS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Eligos','The Fifteenth Spirit in Order is Eligos, a Great Duke, and appeareth in the form of a goodly Knight, carrying a Lance, an Ensign, and a Serpent. He discovereth hidden things, and knoweth things to come; and of Wars, and how the Soldiers will or shall meet. He causeth the Love of Lords and Great Persons. He governeth 60 Legions of Spirits. His Seal is this, etc. (16.) ZEPAR.—The Sixteenth Spirit is Zepar.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_FOCALOR_GOET','ENT_GOE_FOCALOR','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Focalor','The Forty-first Spirit is Focalor, or Forcalor, or Furcalor. He is a Mighty Duke and Strong. He appeareth in the Form of a Man with Gryphon''s Wings. His office is to slay Men, and to drown them in the Waters, and to overthrow Ships of War, for he hath Power over both Winds and Seas; but he will not hurt any man or thing if he be commanded to the contrary by the Exorcist.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_FORAS_GOET','ENT_GOE_FORAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Foras','The Thirty-first Spirit is Foras. He is a Mighty President, and appeareth in the Form of a Strong Man in Human Shape. He can give the understanding to Men how they may know the Virtues of all Herbs and Precious Stones. He teacheth the Arts of Logic and Ethics in all their parts. If desired he maketh men invisible, and to live long, and to be eloquent. He can discover Treasures and recover things Lost.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_FORNEUS_GOET','ENT_GOE_FORNEUS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Forneus','The Thirtieth Spirit is Forneus. He is a Mighty and Great Marquis, and appeareth in the Form of a Great Sea-Monster. He teacheth, and maketh men wonderfully knowing in the Art of Rhetoric. He causeth men to have a Good Name, and to have the knowledge and understanding of Tongues. He maketh one to be beloved of his Foes as well as of his Friends.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_FURCAS_GOET','ENT_GOE_FURCAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Furcas','The Fiftieth Spirit is Furcas. He is a Knight, and appeareth in the Form of a Cruel Old Man with a long Beard and a hoary Head, riding upon a pale-coloured Horse, with a Sharp Weapon in his hand. His Office is to teach the Arts of Philosophy, Astrology, Rhetoric, Logic, Cheiromancy, and Pyromancy, in all their parts, and perfectly. He hath under his Power 20 Legions of Spirits. His Seal, or Mark, is thus made, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_FURFUR_GOET','ENT_GOE_FURFUR','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Furfur','The Thirty-fourth Spirit is Furfur. He is a Great and Mighty Earl, appearing in the Form of an Hart with a Fiery Tail. He never speaketh truth unless he be compelled, or brought up within a triangle, △. Being therein, he will take upon himself the Form of an Angel. Being bidden, he speaketh with a hoarse voice. Also he will wittingly urge Love between Man and Woman.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_GLASYA_LABOLAS_GOET','ENT_GOE_GLASYA_LABOLAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Glasya-Labolas','The Twenty-fifth Spirit is Glasya-Labolas. He is a Mighty President and Earl, and showeth himself in the form of a Dog with Wings like a Gryphon. He teacheth all Arts and Sciences in an instant, and is an Author of Bloodshed and Manslaughter. He teacheth all things Past, and to Come. If desired he causeth the love both of Friends and of Foes. He can make a Man to go Invisible.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_GREMORY_GOET','ENT_GOE_GREMORY','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Gremory','The Fifty-sixth Spirit is Gremory, or Gamori. He is a Duke Strong and Powerful, and appeareth in the Form of a Beautiful Woman, with a Duchess''s Crown tied about her waist, and riding on a Great Camel. His Office is to tell of all Things Past, Present, and to Come; and of Treasures Hid, and what they lie in; and to procure the Love of Women both Young and Old. He governeth 26 Legions of Spirits, and his Seal is this, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_GUSION_GOET','ENT_GOE_GUSION','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Gusion','The Eleventh Spirit in order is a great and strong Duke, called Gusion. He appeareth like a Xenopilus. He telleth all things, Past, Present, and to Come, and showeth the meaning and resolution of all questions thou mayest ask. He conciliateth and reconcileth friendships, and giveth Honour and Dignity unto any. He ruleth over 40 Legions of Spirits. His Seal is this, the which wear thou as aforesaid.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_HAAGENTI_GOET','ENT_GOE_HAAGENTI','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Haagenti','The Forty-eighth Spirit is Haagenti. He is a President, appearing in the Form of a Mighty Bull with Gryphon''s Wings. This is at first, but after, at the Command of the Exorcist he putteth on Human Shape. His Office is to make Men wise, and to instruct them in divers things; also to Transmute all Metals into Gold; and to change Wine into Water, and Water into Wine. He governeth 33 Legions of Spirits, and his Seal is this, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_HALPHAS_GOET','ENT_GOE_HALPHAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Halphas','The Thirty-eighth Spirit is Halphas, or Malthous (or Malthas). He is a Great Earl, and appeareth in the Form of a Stock-Dove. He speaketh with a hoarse Voice. His Office is to build up Towers, and to furnish them with Ammunition and Weapons, and to send Men-of-War to places appointed. He ruleth over 26 Legions of Spirits, and his Seal is this, etc. (39.) MALPHAS.—The Thirty-ninth Spirit is Malphas.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_HAURES_GOET','ENT_GOE_HAURES','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Haures (Flauros)','The Sixty-fourth Spirit is Haures, or Hauras, or Havres, or Flauros. He is a Great Duke, and appeareth at first like a Leopard, Mighty, Terrible, and Strong, but after a while, at the Command of the Exorcist, he putteth on Human Shape with Eyes Flaming and Fiery, and a most Terrible Countenance. He giveth True Answers of all things, Present, Past, and to Come.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_IPOS_GOET','ENT_GOE_IPOS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Ipos','The Twenty-second Spirit is Ipos. He is an Earl, and a Mighty Prince, and appeareth in the form of an Angel with a Lion''s Head, and a Goose''s Foot, and Hare''s Tail. He knoweth all things Past, Present, and to Come. He maketh men witty and bold. He governeth 36 Legions of Spirits. His Seal is this, which thou shalt wear, etc. (23.) AIM.—The Twenty-third Spirit is Aim. He is a Great Strong Duke.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_LERAJE_GOET','ENT_GOE_LERAJE','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Leraje (Leraie)','The Fourteenth Spirit is called Leraje (or Leraie). He is a Marquis Great in Power, showing himself in the likeness of an Archer clad in Green, and carrying a Bow and Quiver. He causeth all great Battles and Contests; and maketh wounds to putrefy that are made with Arrows by Archers. This belongeth unto Sagittary. He governeth 30 Legions of Spirits, and this is his Seal, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_MALPHAS_GOET','ENT_GOE_MALPHAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Malphas','The Thirty-ninth Spirit is Malphas. He appeareth at first like a Crow, but after he will put on Human Shape at the request of the Exorcist, and speak with a hoarse Voice. He is a Mighty President and Powerful. He can build Houses and High Towers, and can bring to thy Knowledge Enemies'' Desires and Thoughts, and that which they have done. He giveth Good Familiars.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_MARAX_GOET','ENT_GOE_MARAX','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Marax (Morax)','The Twenty-first Spirit is Marax. He is a Great Earl and President. He appeareth like a great Bull with a Man''s face. His office is to make Men very knowing in Astronomy, and all other Liberal Sciences; also he can give good Familiars, and wise, knowing the virtues of Herbs and Stones which be precious. He governeth 30 Legions of Spirits, and his Seal is this, which must be made and worn as aforesaid, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_MARBAS_GOET','ENT_GOE_MARBAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Marbas','The fifth Spirit is Marbas. He is a Great President, and appeareth at first in the form of a Great Lion, but afterwards, at the request of the Master, he putteth on Human Shape. He answereth truly of things Hidden or Secret. He causeth Diseases and cureth them. Again, he giveth great Wisdom and Knowledge in Mechanical Arts; and can change men into other shapes. He governeth 36 Legions of Spirits.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_MARCHOSIAS_GOET','ENT_GOE_MARCHOSIAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Marchosias','The Thirty-fifth Spirit is Marchosias. He is a Great and Mighty Marquis, appearing at first in the Form of a Wolf having Gryphon''s Wings, and a Serpent''s Tail, and Vomiting Fire out of his mouth. But after a time, at the command of the Exorcist he putteth on the Shape of a Man. And he is a strong fighter. He was of the Order of Dominations. He governeth 30 Legions of Spirits.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_MURMUR_GOET','ENT_GOE_MURMUR','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Murmur','The Fifty-fourth Spirit is called Murmur, or Murmus, or Murmux. He is a Great Duke, and an Earl; and appeareth in the Form of a Warrior riding upon a Gryphon, with a Ducal Crown upon his Head. There do go before him those his Ministers with great Trumpets sounding.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_NABERIUS_GOET','ENT_GOE_NABERIUS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Naberius','The Twenty-fourth Spirit is Naberius. He is a most valiant Marquis, and showeth in the form of a Black Crane, fluttering about the Circle, and when he speaketh it is with a hoarse voice. He maketh men cunning in all Arts and Sciences, but especially in the Art of Rhetoric. He restoreth lost Dignities and Honours. He governeth 19 Legions of Spirits. His Seal is this, which is to be worn, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_ORIAS_GOET','ENT_GOE_ORIAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Orias','The Fifty-ninth Spirit is Oriax, or Orias. He is a Great Marquis, and appeareth in the Form of a Lion, riding upon a Horse Mighty and Strong, with a Serpent''s Tail; and he holdeth in his Right Hand two Great Serpents hissing. His Office is to teach the Virtues of the Stars, and to know the Mansions of the Planets, and how to understand their Virtues.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_OROBAS_GOET','ENT_GOE_OROBAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Orobas','The Fifty-fifth Spirit is Orobas. He is a great and Mighty Prince, appearing at first like a Horse; but after the command of the Exorcist he putteth on the Image of a Man. His Office is to discover all things Past, Present, and to Come; also to give Dignities, and Prelacies, and the Favour of Friends and of Foes. He giveth True Answers of Divinity, and of the Creation of the World.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_OSE_GOET','ENT_GOE_OSE','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Ose','Ose; (58.) Amy; (61.) Zagan; (62.) Valac. (Seal in Copper and Silver alike equal.) EARLS, or COUNTS.—(17.) Botis; (21.) Marax; (25.) Glasya-Labolas; (27.) Ronové; (34.) Furfur; (38.) Halphas; (40.) Räum; (45.) Viné; (46.) Bifrons; (72.) Andromalius. (Seal in Lead.) KNIGHTS.—(50.) Furcas.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_PAIMON_GOET','ENT_GOE_PAIMON','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Paimon','The Ninth Spirit in this Order is Paimon, a Great King, and very obedient unto LUCIFER. He appeareth in the form of a Man sitting upon a Dromedary with a Crown most glorious upon his head. There goeth before him also an Host of Spirits, like Men with Trumpets and well sounding Cymbals, and all other sorts of Musical Instruments.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_PHENEX_GOET','ENT_GOE_PHENEX','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Phenex','The Thirty-Seventh Spirit is Phenex (or Pheynix). He is a great Marquis, and appeareth like the Bird Phœnix, having the Voice of a Child. He singeth many sweet notes before the Exorcist, which he must not regard, but by-and-by he must bid him put on Human Shape. Then he will speak marvellously of all wonderful Sciences if required. He is a Poet, good and excellent. And he will be willing to perform thy requests.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_PURSON_GOET','ENT_GOE_PURSON','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Purson','The Twentieth Spirit is Purson, a Great King. His appearance is comely, like a Man with a Lion''s face, carrying a cruel Viper in his hand, and riding upon a Bear. Going before him are many Trumpets sounding. He knoweth all things hidden, and can discover Treasure, and tell all things Past, Present, and to Come.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_SABNOCK_GOET','ENT_GOE_SABNOCK','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Sabnock','The Forty-third Spirit, as King Solomon commanded them into the Vessel of Brass, is called Sabnock, or Savnok. He is a Marquis, Mighty, Great and Strong, appearing in the Form of an Armed Soldier with a Lion''s Head, riding on a pale-coloured horse. His office is to build high Towers, Castles and Cities, and to furnish them with Armour, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_SALLOS_GOET','ENT_GOE_SALLOS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Sallos','The Nineteenth Spirit is Sallos (or Saleos). He is a Great and Mighty Duke, and appeareth in the form of a gallant Soldier riding on a Crocodile, with a Ducal Crown on his head, but peaceably. He causeth the Love of Women to Men, and of Men to Women; and governeth 30 Legions of Spirits. His Seal is this, etc. (20.) PURSON.—The Twentieth Spirit is Purson, a Great King.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_SAMIGINA_GOET','ENT_GOE_SAMIGINA','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Samigina (Gamigin)','The Fourth Spirit is Samigina, a Great Marquis. He appeareth in the form of a little Horse or Ass, and then into Human shape doth he change himself at the request of the Master. He speaketh with a hoarse voice. He ruleth over 30 Legions of Inferiors. He teaches all Liberal Sciences, and giveth account of Dead Souls that died in sin. And his Seal is this, which is to be worn before the Magician when he is Invocator, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_SEERE_GOET','ENT_GOE_SEERE','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Seere','The Seventieth Spirit is Seere, Sear, or Seir. He is a Mighty Prince, and Powerful, under AMAYMON, King of the East. He appeareth in the Form of a Beautiful Man, riding upon a Winged Horse. His Office is to go and come; and to bring abundance of things to pass on a sudden, and to carry or recarry anything whither thou wouldest have it to go, or whence thou wouldest have it from.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_SHAX_GOET','ENT_GOE_SHAX','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Shax','The Forty-fourth Spirit is Shax, or Shaz (or Shass). He is a Great Marquis and appeareth in the Form of a Stock-Dove, speaking with a voice hoarse, but yet subtle. His Office is to take away the Sight, Hearing, or Understanding of any Man or Woman at the command of the Exorcist; and to steal money out of the houses of Kings, and to carry it again in 1,200 years.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_SITRI_GOET','ENT_GOE_SITRI','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Sitri','The Twelfth Spirit is Sitri. He is a Great Prince and appeareth at first with a Leopard''s head and the Wings of a Gryphon, but after the command of the Master of the Exorcism he putteth on Human shape, and that very beautiful. He enflameth men with Women''s love, and Women with Men''s love; and causeth them also to show themselves naked if it be desired. He governeth 60 Legions of Spirits.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_STOLAS_GOET','ENT_GOE_STOLAS','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Stolas','The Thirty-sixth Spirit is Stolas, or Stolos. He is a Great and Powerful Prince, appearing in the Shape of a Mighty Raven at first before the Exorcist; but after he taketh the image of a Man. He teacheth the Art of Astronomy, and the Virtues of Herbs and Precious Stones. He governeth 26 Legions of Spirits; and his Seal is this, which is, etc. (37.) PHENEX.—The Thirty-Seventh Spirit is Phenex (or Pheynix).','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_VALEFOR_GOET','ENT_GOE_VALEFOR','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Valefor','The Sixth Spirit is Valefor. He is a mighty Duke, and appeareth in the shape of a Lion with an Ass''s Head, bellowing. He is a good Familiar, but tempteth them he is a familiar of to steal. He governeth 10 Legions of Spirits. His Seal is this, which is to be worn, whether thou wilt have him for a Familiar, or not. (7.) AMON.—The Seventh Spirit is Amon. He is a Marquis great in power, and most stern.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_VAPULA_GOET','ENT_GOE_VAPULA','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Vapula','The Sixtieth Spirit is Vapula, or Naphula. He is a Duke Great, Mighty, and Strong; appearing in the Form of a Lion with Gryphon''s Wings. His Office is to make Men Knowing in all Handcrafts and Professions, also in Philosophy, and other Sciences. He governeth 36 Legions of Spirits, and his Seal or Character is thus made, and thou shalt wear it as aforesaid, etc. (61.) ZAGAN.—The Sixty-first Spirit is Zagan.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_VASSAGO_GOET','ENT_GOE_VASSAGO','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Vassago','The Third Spirit is a Mighty Prince, being of the same nature as Agares. He is called Vassago. This Spirit is of a Good Nature, and his office is to declare things Past and to Come, and to discover all things Hid or Lost. And he governeth 26 Legions of Spirits, and this is his Seal. (4.) SAMIGINA, or GAMIGIN.—The Fourth Spirit is Samigina, a Great Marquis.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_VEPAR_GOET','ENT_GOE_VEPAR','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Vepar','The Forty-second Spirit is Vepar, or Vephar. He is a Duke Great and Strong and appeareth like a Mermaid. His office is to govern the Waters, and to guide Ships laden with Arms, Armour, and Ammunition, etc., thereon. And at the request of the Exorcist he can cause the seas to be right stormy and to appear full of ships. Also he maketh men to die in Three Days by Putrefying Wounds or Sores, and causing Worms to breed in them.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_VOLAC_GOET','ENT_GOE_VOLAC','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Volac','The Sixty-second Spirit is Volac, or Valak, or Valu. He is a President Mighty and Great, and appeareth like a Child with Angel''s Wings, riding on a Two-headed Dragon. His Office is to give True Answers of Hidden Treasures, and to tell where Serpents may be seen. The which he will bring unto the Exorciser without any Force or Strength being by him employed. He governeth 38 Legions of Spirits, and his Seal is thus.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_VUAL_GOET','ENT_GOE_VUAL','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Vual','The Forty-seventh Spirit is Uvall, or Vual, or Voval. He is a Duke, Great, Mighty, and Strong; and appeareth in the Form of a Mighty Dromedary at the first, but after a while at the Command of the Exorcist he putteth on Human Shape, and speaketh the Egyptian Tongue, but not perfectly. His Office is to procure the Love of Woman, and to tell Things Past, Present, and to Come.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_ZAGAN_GOET','ENT_GOE_ZAGAN','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Zagan','The Sixty-first Spirit is Zagan. He is a Great King and President, appearing at first in the Form of a Bull with Gryphon''s Wings; but after a while he putteth on Human Shape. He maketh Men Witty. He can turn Wine into Water, and Blood into Wine, also Water into Wine. He can turn all Metals into Coin of the Dominion that Metal is of. He can even make Fools wise. He governeth 33 Legions of Spirits, and his Seal is this, etc.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1),
('CIT_GOE_ZEPAR_GOET','ENT_GOE_ZEPAR','SRC_LEMEGETON','The Lesser Key of Solomon (Ars Goetia)','entry for Zepar','The Sixteenth Spirit is Zepar. He is a Great Duke, and appeareth in Red Apparel and Armour, like a Soldier. His office is to cause Women to love Men, and to bring them together in love. He also maketh them barren. He governeth 26 Legions of Inferior Spirits, and his Seal is this, which he obeyeth when he seeth it. (17.) BOTIS.—The Seventeenth Spirit is Botis, a Great President, and an Earl.','S. L. MacGregor Mathers & A. Crowley',1904,'https://www.gutenberg.org/ebooks/72679',NULL,'primary-verbatim','Early-modern grimoire (the Goetia descriptions); a learned-magic literary tradition, not a mainstream cult.',false,NULL,DATE '2026-06-18','name-anchored entry extraction + substring gate (Gutenberg #72679)',1)
